mapper.select:
SELECT IFNULL((
    SELECT ats.note
    FROM tb_account_tally_sheet ats
    WHERE ats.account_id = #{account_id}
      AND ats.count_year = #{year}
      AND ats.count_month = #{month}
    ORDER BY ats.mod_dt DESC
    LIMIT 1
), '') AS note

mapper.update:
UPDATE tb_account_tally_sheet
SET note = #{note}
WHERE account_id = #{account_id}
  AND count_year = #{year}
  AND count_month = #{month}

