INSERT INTO tb_account_mapping_v2 (account_id, type, reg_dt, del_dt, del_yn) VALUES ( #{account_id} , #{type} , DATE_FORMAT(CONVERT_TZ(NOW(), '+00:00', '+09:00'), '%Y-%m-%d') NULL
, DATE_FORMAT(CONVERT_TZ(NOW(), '+00:00', '+09:00'), '%Y-%m-%d') NULL
, #{del_yn, jdbcType=CHAR}
) ON DUPLICATE KEY UPDATE account_id = #{account_id}, type = #{type},
