SELECT am.* FROM ( SELECT T.member_id, T.account_id, T2.account_name, T.name, T.cor_type, T.join_dt, T.del_dt, T.del_yn, T.display_yn, T.position_type, T.idx, T.start_time, T.end_time, T.salary, T.relation, T.del_note, T.rct_notice, T.note, T.address, T.rrn, T.account_number, T.phone, T.contract_type, DATE_FORMAT(T.act_join_dt, '%Y-%m-%d') AS act_join_dt, DATE_FORMAT(T.ret_set_dt, '%Y-%m-%d') AS ret_set_dt, CASE WHEN T.national_pension IS NULL OR TRIM(T.national_pension) = '' THEN '' WHEN T.national_pension = '미해당' THEN '미해당' WHEN STR_TO_DATE(T.national_pension, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(T.national_pension, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS national_pension, CASE WHEN T.health_insurance IS NULL OR TRIM(T.health_insurance) = '' THEN '' WHEN T.health_insurance = '미해당' THEN '미해당' WHEN STR_TO_DATE(T.health_insurance, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(T.health_insurance, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS health_insurance, CASE WHEN T.industrial_insurance IS NULL OR TRIM(T.industrial_insurance) = '' THEN '' WHEN T.industrial_insurance = '미해당' THEN '미해당' WHEN STR_TO_DATE(T.industrial_insurance, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(T.industrial_insurance, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS industrial_insurance, CASE WHEN T.employment_insurance IS NULL OR TRIM(T.employment_insurance) = '' THEN '' WHEN T.employment_insurance = '미해당' THEN '미해당' WHEN STR_TO_DATE(T.employment_insurance, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(T.employment_insurance, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS employment_insurance, DATE_FORMAT(T.loss_major_insurances, '%Y-%m-%d') AS loss_major_insurances, T.employment_contract, T.subsidy, T.headoffice_note, T.id, T.bankbook, IFNULL(T.ledger_yn, 'Y') AS ledger_yn FROM tb_account_members T JOIN tb_account T2 ON T.account_id = T2.account_id WHERE 1=1
AND T.del_yn = #{del_yn}
AND T.member_id = #{member_id}
AND T.name LIKE CONCAT('%', #{name}, '%')
AND T.account_id = #{account_id}
UNION ALL SELECT M.member_id, M.account_id, B.account_name, A.name, A.cor_type, A.join_dt, A.del_dt, A.del_yn, A.display_yn, A.position_type, A.idx, A.start_time, A.end_time, A.salary, A.relation, A.del_note, A.rct_notice, A.note, A.address, A.rrn, A.account_number, A.phone, A.contract_type, DATE_FORMAT(A.act_join_dt, '%Y-%m-%d') AS act_join_dt, DATE_FORMAT(A.ret_set_dt, '%Y-%m-%d') AS ret_set_dt, CASE WHEN A.national_pension IS NULL OR TRIM(A.national_pension) = '' THEN '' WHEN A.national_pension = '미해당' THEN '미해당' WHEN STR_TO_DATE(A.national_pension, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(A.national_pension, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS national_pension, CASE WHEN A.health_insurance IS NULL OR TRIM(A.health_insurance) = '' THEN '' WHEN A.health_insurance = '미해당' THEN '미해당' WHEN STR_TO_DATE(A.health_insurance, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(A.health_insurance, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS health_insurance, CASE WHEN A.industrial_insurance IS NULL OR TRIM(A.industrial_insurance) = '' THEN '' WHEN A.industrial_insurance = '미해당' THEN '미해당' WHEN STR_TO_DATE(A.industrial_insurance, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(A.industrial_insurance, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS industrial_insurance, CASE WHEN A.employment_insurance IS NULL OR TRIM(A.employment_insurance) = '' THEN '' WHEN A.employment_insurance = '미해당' THEN '미해당' WHEN STR_TO_DATE(A.employment_insurance, '%Y-%m-%d') IS NOT NULL THEN DATE_FORMAT(STR_TO_DATE(A.employment_insurance, '%Y-%m-%d'), '%Y-%m-%d') ELSE '' END AS employment_insurance, DATE_FORMAT(A.loss_major_insurances, '%Y-%m-%d') AS loss_major_insurances, A.employment_contract, A.subsidy, A.headoffice_note, A.id, A.bankbook, IFNULL(A.ledger_yn, 'Y') AS ledger_yn FROM tb_account_util_member_mapping M JOIN tb_account_members A ON M.member_id = A.member_id JOIN tb_account B ON M.account_id = B.account_id WHERE 1=1
AND (A.del_yn = #{del_yn} OR M.del_yn = #{del_yn})
AND A.name LIKE CONCAT('%', #{name}, '%')
AND M.account_id = #{account_id}
) am ORDER BY am.account_id, am.position_type, am.name;

SELECT am.* FROM ( SELECT T.member_id, T.account_id, T2.account_name, T.name, T.cor_type, T.join_dt, T.del_dt, T.del_yn, T.display_yn, T.position_type, T.idx, T.start_time, T.end_time, T.salary, T.relation, T.del_note, T.rct_notice, T.note, T.address, T.rrn, T.account_number, T.phone, T.contract_type, DATE_FORMAT(T.act_join_dt, '%Y-%m-%d') AS act_join_dt, DATE_FORMAT(T.ret_set_dt, '%Y-%m-%d') AS ret_set_dt, DATE_FORMAT(T.national_pension, '%Y-%m-%d') AS national_pension, DATE_FORMAT(T.health_insurance, '%Y-%m-%d') AS health_insurance, DATE_FORMAT(T.industrial_insurance, '%Y-%m-%d') AS industrial_insurance, DATE_FORMAT(T.employment_insurance, '%Y-%m-%d') AS employment_insurance, DATE_FORMAT(T.loss_major_insurances, '%Y-%m-%d') AS loss_major_insurances, T.employment_contract, T.subsidy, T.headoffice_note, T.id, T.bankbook FROM tb_account_members T JOIN tb_account T2 ON T.account_id = T2.account_id WHERE 1=1
AND T.del_yn = #{del_yn}
UNION ALL SELECT A.member_id, A.account_id, CASE WHEN A.position_type = '6' THEN '유틸' WHEN A.position_type = '7' THEN '통합' END AS account_name, A.name, A.cor_type, A.join_dt, A.del_dt, A.del_yn, A.display_yn, A.position_type, A.idx, A.start_time, A.end_time, CASE WHEN A.position_type = 7 THEN A.salary * (SELECT COUNT(1) FROM tb_account_util_member_mapping T WHERE T.member_id = A.member_id) ELSE A.salary END AS salary, A.relation, A.del_note, A.rct_notice, A.note, A.address, A.rrn, A.account_number, A.phone, A.contract_type, DATE_FORMAT(A.act_join_dt, '%Y-%m-%d') AS act_join_dt, DATE_FORMAT(A.ret_set_dt, '%Y-%m-%d') AS ret_set_dt, DATE_FORMAT(A.national_pension, '%Y-%m-%d') AS national_pension, DATE_FORMAT(A.health_insurance, '%Y-%m-%d') AS health_insurance, DATE_FORMAT(A.industrial_insurance, '%Y-%m-%d') AS industrial_insurance, DATE_FORMAT(A.employment_insurance, '%Y-%m-%d') AS employment_insurance, DATE_FORMAT(A.loss_major_insurances, '%Y-%m-%d') AS loss_major_insurances, A.employment_contract, A.subsidy, A.headoffice_note, A.id, A.bankbook FROM tb_account_members A WHERE A.position_type in (6,7)
AND A.del_yn = #{del_yn}
) am ORDER BY am.account_id, am.position_type, am.name;

SELECT T.member_id, T.account_id, T2.account_name, T.name, T.position_type, T.idx, T.start_time, T.end_time, T.salary, T.note, T.position_type, T.address, T.rrn, T.account_number, T.phone, T.contract_type, DATE_FORMAT(T.act_join_dt, '%Y-%m-%d') AS act_join_dt, T.employment_contract, T.id, T.bankbook, T.use_yn, T.cor_type FROM tb_account_rec_management T JOIN tb_account T2 ON T.account_id = T2.account_id WHERE 1=1
AND T.use_yn = #{use_yn}
AND T.account_id = #{account_id}
ORDER BY T.account_id, T.position_type

