INSERT INTO tb_account_diners_number
account_id, diner_year, diner_month, diner_date, breakfast, lunch, dinner, daycare_lunch, daycare_diner, employ, note, total, breakcancel, lunchcancel, dinnercancel, ceremony, extra_diet1_price, extra_diet2_price, extra_diet3_price, extra_diet4_price, extra_diet5_price, special_yn, ceremony2, daycare_breakfast, employ_breakfast, employ_lunch, employ_dinner, breakfast2, lunch2, dinner2, daycare_elderly_lunch, daycare_elderly_dinner, daycare_employ_breakfast, daycare_employ_lunch, daycare_employ_dinner, working_day
VALUES
#{account_id}, #{diner_year}, #{diner_month}, #{diner_date}, #{breakfast}, #{lunch}, #{dinner}, #{daycare_lunch}, #{daycare_diner}, #{employ}, #{note}, #{total}, #{breakcancel}, #{lunchcancel}, #{dinnercancel}, #{ceremony}, #{extra_diet1_price}, #{extra_diet2_price}, #{extra_diet3_price}, #{extra_diet4_price}, #{extra_diet5_price}, #{special_yn}, #{ceremony2}, #{daycare_breakfast}, #{employ_breakfast}, #{employ_lunch}, #{employ_dinner}, #{breakfast2}, #{lunch2}, #{dinner2}, #{daycare_elderly_lunch}, #{daycare_elderly_dinner}, #{daycare_employ_breakfast}, #{daycare_employ_lunch}, #{daycare_employ_dinner}, #{working_day}
ON DUPLICATE KEY UPDATE
account_id=#{account_id}, diner_year=#{diner_year}, diner_month=#{diner_month}, diner_date=#{diner_date}, breakfast=#{breakfast}, lunch=#{lunch}, dinner=#{dinner}, daycare_lunch=#{daycare_lunch}, daycare_diner=#{daycare_diner}, employ=#{employ}, note=#{note}, total=#{total}, breakcancel=#{breakcancel}, lunchcancel=#{lunchcancel}, dinnercancel=#{dinnercancel}, ceremony=#{ceremony}, extra_diet1_price=#{extra_diet1_price}, extra_diet2_price=#{extra_diet2_price}, extra_diet3_price=#{extra_diet3_price}, extra_diet4_price=#{extra_diet4_price}, extra_diet5_price=#{extra_diet5_price}, special_yn=#{special_yn}, ceremony2=#{ceremony2}, daycare_breakfast=#{daycare_breakfast}, employ_breakfast=#{employ_breakfast}, employ_lunch=#{employ_lunch}, employ_dinner=#{employ_dinner}, breakfast2=#{breakfast2}, lunch2=#{lunch2}, dinner2=#{dinner2}, daycare_elderly_lunch=#{daycare_elderly_lunch}, daycare_elderly_dinner=#{daycare_elderly_dinner}, daycare_employ_breakfast=#{daycare_employ_breakfast}, daycare_employ_lunch=#{daycare_employ_lunch}, daycare_employ_dinner=#{daycare_employ_dinner}, working_day=#{working_day}

mapper.select:
SELECT t.*, ROUND(t.person_total / t.sales_total * 100, 1) AS person_ratio FROM ( SELECT b.account_id, b.account_name, b.base_year, b.base_month, (SELECT m0.sales_total FROM tb_account_managerment_table m0 WHERE m0.account_id = b.account_id AND m0.year = b.base_year AND m0.month = b.base_month LIMIT 1) AS sales_total, (SELECT m0.person_total FROM tb_account_managerment_table m0 WHERE m0.account_id = b.account_id AND m0.year = b.base_year AND m0.month = b.base_month LIMIT 1) AS person_total,
(SELECT mc.person_cost FROM tb_account_managerment_table mc WHERE mc.account_id = b.account_id AND mc.year = CASE WHEN #{month} = 1 THEN #{year} - 1 ELSE #{year} END AND mc.month = CASE WHEN #{month} = 1 THEN 12 ELSE #{month} - 1 END LIMIT 1) AS recent_month_person_cost, (SELECT mc.dispatch_cost FROM tb_account_managerment_table mc WHERE mc.account_id = b.account_id AND mc.year = CASE WHEN #{month} = 1 THEN #{year} - 1 ELSE #{year} END AND mc.month = CASE WHEN #{month} = 1 THEN 12 ELSE #{month} - 1 END LIMIT 1) AS recent_month_dispatch_cost, (SELECT m1.sales_total FROM tb_account_managerment_table m1 WHERE m1.account_id = b.account_id AND m1.year = CASE WHEN b.base_month = 1 THEN b.base_year - 1 ELSE b.base_year END AND m1.month = CASE WHEN b.base_month = 1 THEN 12 ELSE b.base_month - 1 END LIMIT 1) AS prev_month_sales_total, (SELECT m1.person_total FROM tb_account_managerment_table m1 WHERE m1.account_id = b.account_id AND m1.year = CASE WHEN b.base_month = 1 THEN b.base_year - 1 ELSE b.base_year END AND m1.month = CASE WHEN b.base_month = 1 THEN 12 ELSE b.base_month - 1 END LIMIT 1) AS prev_month_person_total, (SELECT m2.sales_total FROM tb_account_managerment_table m2 WHERE m2.account_id = b.account_id AND m2.year = CASE WHEN b.base_month <= 2 THEN b.base_year - 1 ELSE b.base_year END AND m2.month = CASE WHEN b.base_month <= 2 THEN b.base_month + 10 ELSE b.base_month - 2 END LIMIT 1) AS prev_prev_month_sales_total, (SELECT m2.person_total FROM tb_account_managerment_table m2 WHERE m2.account_id = b.account_id AND m2.year = CASE WHEN b.base_month <= 2 THEN b.base_year - 1 ELSE b.base_year END AND m2.month = CASE WHEN b.base_month <= 2 THEN b.base_month + 10 ELSE b.base_month - 2 END LIMIT 1) AS prev_prev_month_person_total FROM ( SELECT a.account_id, a.account_name, COALESCE( (SELECT NULLIF(m1.year, 0) FROM tb_account_managerment_table m1 WHERE m1.account_id = a.account_id AND m1.year = #{year} AND m1.month = #{month} AND NULLIF(m1.person_total, 0) IS NOT NULL AND NULLIF(m1.sales_total, 0) IS NOT NULL LIMIT 1), (SELECT m2.year FROM tb_account_managerment_table m2 WHERE m2.account_id = a.account_id AND m2.year = CASE WHEN #{month} <= 2 THEN #{year} - 1 ELSE #{year} END AND m2.month = CASE WHEN #{month} <= 2 THEN #{month} + 10 ELSE #{month} - 2 END LIMIT 1) ) AS base_year, COALESCE( (SELECT NULLIF(m1.month, 0) FROM tb_account_managerment_table m1 WHERE m1.account_id = a.account_id AND m1.year = #{year} AND m1.month = #{month} AND NULLIF(m1.person_total, 0) IS NOT NULL AND NULLIF(m1.sales_total, 0) IS NOT NULL LIMIT 1), (SELECT m2.month FROM tb_account_managerment_table m2 WHERE m2.account_id = a.account_id AND m2.year = CASE WHEN #{month} <= 2 THEN #{year} - 1 ELSE #{year} END AND m2.month = CASE WHEN #{month} <= 2 THEN #{month} + 10 ELSE #{month} - 2 END LIMIT 1) ) AS base_month FROM tb_account a WHERE a.del_yn = 'N' AND a.account_id NOT IN ( 20260122065002, 20260122071337, 20260122071857, 20260122072114, 20260122072245, 20260122072529, 20260122072732 )
AND a.account_id = #{account_id}
) b WHERE b.base_year IS NOT NULL AND b.base_month IS NOT NULL ) t WHERE t.sales_total IS NOT NULL AND t.sales_total > 0 AND t.person_total IS NOT NULL AND ROUND(t.person_total / t.sales_total * 100, 1) >= 45 ORDER BY (t.person_total / t.sales_total) DESC



